/* GPO Remediator Enterprise UI — CIS v4.0.0. Real GPO execution stays in the existing backend. */
(() => {
'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const T={
 az:{dashboard:'İdarə paneli',benchmark:'Benchmark',operations:'Əməliyyatlar',settings:'Sazlamalar',connected:'Qoşulub',setup:'Setup tələb olunur',refresh:'Yenilə',theme:'Tema',language:'Dil',domains:'Benchmark domain-ləri',controls:'Control',ready:'Remediation hazır',planned:'Mapping gözləyir',manual:'Manual control',search:'Control ID, ad və ya açar söz axtarın…',allLevels:'Bütün səviyyələr',allTypes:'Bütün növlər',overview:'Overview',remediation:'Remediation',impact:'Impact',verification:'Verification',audit:'Audit',back:'Benchmark-a qayıt',target:'Target & policy',preview:'Plan hazırla',approval:'Change approval',apply:'Tətbiq et',history:'Son əməliyyatlar',noHistory:'Hələ əməliyyat yoxdur.',noSelection:'Control seçilməyib',open:'Aç',logout:'Ayrıl',connect:'AD-yə qoşul',risk:'Operational risk'},
 en:{dashboard:'Dashboard',benchmark:'Benchmark',operations:'Operations',settings:'Settings',connected:'Connected',setup:'Setup required',refresh:'Refresh',theme:'Theme',language:'Language',domains:'Benchmark domains',controls:'Controls',ready:'Remediation ready',planned:'Mapping pending',manual:'Manual control',search:'Search control ID, policy name or keyword…',allLevels:'All levels',allTypes:'All types',overview:'Overview',remediation:'Remediation',impact:'Impact',verification:'Verification',audit:'Audit',back:'Back to benchmark',target:'Target & policy',preview:'Generate plan',approval:'Change approval',apply:'Apply change',history:'Recent operations',noHistory:'No operations yet.',noSelection:'No control selected',open:'Open',logout:'Disconnect',connect:'Connect to AD',risk:'Operational risk'}
};
const state={session:null,service:null,inventory:null,readiness:null,settings:[],history:[],catalog:null,plan:null,busy:false,notice:'',query:'',level:'ALL',automation:'ALL',savedView:'ALL',bulkMode:false,bulkSelection:new Set(),expandedTop:new Set(['1']),expandedSub:new Set(),selectedRule:null,tab:'overview',opsFilter:'ALL',theme:localStorage.getItem('gr-theme')||'light',lang:localStorage.getItem('gr-lang')||'az',approval:{reference:'',approver:'',reviewed:false},exception:{enabled:false,reason:'',owner:'',expires:''},favorites:new Set(JSON.parse(localStorage.getItem('gr-favorites')||'[]')),commandOpen:false,notificationOpen:false,gpoSearch:'',gpoPickerOpen:false,buildLabel:'2026.09.25-production-backend',selection:{gpoId:'',scopeDn:'',setting:'',value:14,customValue:'',accountScope:'LocalComputers',refresh:'None',firstLink:false}};
let page,bar;
const tr=k=>T[state.lang]?.[k]||T.en[k]||k;
async function api(path,body){const r=await fetch('/api'+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json',...(body===undefined?{}:{'X-CSRF-Token':state.session.csrfToken})},body:body===undefined?undefined:JSON.stringify(body)});const data=await r.json();if(!r.ok){if(data.code==='GPO_LOGIN_REQUIRED')state.inventory=null;throw Error(data.message||'Request failed');}return data;}
async function loadCatalog(){if(state.catalog)return;const r=await fetch('/benchmark-v4.json',{cache:'no-store'});if(!r.ok)throw Error('CIS Benchmark v4.0.0 catalog could not be loaded.');state.catalog=await r.json();}
function syncBackendMappings(){if(!state.catalog)return;const byId=new Map(state.settings.map(x=>[x.id,x]));for(const r of state.catalog.rules){const m=byId.get(r.id);const writable=!!m&&m.automation==='Automated'&&m.handler!=='Manual';r.backendSetting=writable?m.id:null;r.implementation=writable?'live':m?'manual':'unavailable';r.backendMapping=m||null;}state.catalog.meta.liveMappings=state.catalog.rules.filter(r=>r.implementation==='live').length;}
const topSections=()=>state.catalog?.sections.filter(s=>!s.parentId)||[];
const children=id=>state.catalog?.sections.filter(s=>s.parentId===id)||[];
const directRules=id=>state.catalog?.rules.filter(r=>r.sectionId===id)||[];
const descendants=id=>state.catalog?.rules.filter(r=>r.id.startsWith(id+'.'))||[];
function matchesRule(r){const q=state.query.trim().toLowerCase();const view=state.savedView==='ALL'||(state.savedView==='FAVORITES'&&state.favorites.has(r.id))||(state.savedView==='READY'&&r.implementation==='live')||(state.savedView==='HIGH'&&riskFor(r).name==='High');return view&&(!q||(`${r.id} ${r.title} ${r.description}`).toLowerCase().includes(q))&&(state.level==='ALL'||r.level===state.level)&&(state.automation==='ALL'||r.automation===state.automation);}
function riskFor(r){const t=(r.title||'').toLowerCase();if(r.id.startsWith('1.')||/deny log|user rights|kerberos|ntlm|ldap|firewall|defender|bitlocker|remote desktop|smb|shutdown|administrator account/.test(t))return {name:'High',cls:'high',copy:'May affect authentication, access, remote administration, or production connectivity.'};if(/audit|event log|logging|password|network|security option|service/.test(t))return {name:'Medium',cls:'medium',copy:'Validate scope and application dependencies before broad rollout.'};return {name:'Low',cls:'low',copy:'Lower expected operational impact, but preview and verification are still required.'};}
function implLabel(r){if(r.automation==='Manual')return `<span class="status-chip manual">${tr('manual')}</span>`;return r.implementation==='live'?`<span class="status-chip ready">${tr('ready')}</span>`:`<span class="status-chip planned">${tr('planned')}</span>`;}
function badges(r){return `<span class="mini-chip level">${esc(r.level)}</span><span class="mini-chip">${r.automation==='Automated'?'AUTO':'MANUAL'}</span>${implLabel(r)}`;}
function domainIcon(id){const map={'1':'⌾','2':'◇','5':'▦','9':'◫','17':'≋','18':'⚙','19':'◉'};return map[id]||'◆';}
function topDomainForRule(r){return topSections().find(s=>r.id===s.id||r.id.startsWith(s.id+'.'));}
function sectionTitle(id){return state.catalog.sections.find(s=>s.id===id)?.title||'';}
function renderSubsection(id,depth=0){const s=state.catalog.sections.find(x=>x.id===id);if(!s)return'';const kids=children(id),rules=directRules(id).filter(matchesRule),matching=descendants(id).filter(matchesRule);if(!matching.length&&!rules.length)return'';const open=state.expandedSub.has(id)||!!state.query;return `<div class="ent-sub depth-${Math.min(depth,3)}"><button class="ent-sub-head" data-subsection="${esc(id)}"><span class="sub-id">${esc(id)}</span><span class="sub-copy"><strong>${esc(s.title)}</strong><small>${matching.length||rules.length} matching · ${s.count} total</small></span><span class="chev">${open?'−':'+'}</span></button>${open?`<div class="ent-sub-body">${kids.map(k=>renderSubsection(k.id,depth+1)).join('')}${rules.map(renderRuleRow).join('')}</div>`:''}</div>`;}
function renderRuleRow(r){const risk=riskFor(r),fav=state.favorites.has(r.id),checked=state.bulkSelection.has(r.id);return `<div class="ent-rule-shell">${state.bulkMode?`<label class="bulk-check"><input type="checkbox" data-bulk-rule="${esc(r.id)}" ${checked?'checked':''}><span></span></label>`:''}<button class="ent-rule ${fav?'favorite':''}" data-rule="${esc(r.id)}" aria-label="Open CIS control ${esc(r.id)}: ${esc(r.title)}"><span class="rule-id">${esc(r.id)}</span><span class="rule-copy"><strong>${esc(r.title)}</strong><span class="rule-meta">${badges(r)}<span class="risk-dot ${risk.cls}">${risk.name}</span></span></span><span class="open-arrow">›</span></button><button class="fav-mini ${fav?'active':''}" data-favorite="${esc(r.id)}" title="Favorite" aria-label="${fav?'Remove from favorites':'Add to favorites'}">${fav?'★':'☆'}</button></div>`;}
function renderDomain(s){const rules=descendants(s.id).filter(matchesRule);if(!rules.length)return'';const open=state.expandedTop.has(s.id)||!!state.query,live=rules.filter(r=>r.implementation==='live').length;const l1=rules.filter(r=>r.level==='L1').length,l2=rules.filter(r=>r.level==='L2').length;return `<section class="ent-domain ${open?'open':''}"><button class="ent-domain-head" data-domain="${esc(s.id)}" aria-expanded="${open?'true':'false'}"><span class="domain-icon">${domainIcon(s.id)}</span><span class="domain-title"><span class="domain-kicker">DOMAIN ${esc(s.id)}</span><strong>${esc(s.title)}</strong><small>${rules.length} controls · ${live} ready</small></span><span class="domain-counter"><i>L1</i><b>${l1}</b></span><span class="domain-counter"><i>L2</i><b>${l2}</b></span><span class="domain-progress"><i style="width:${Math.min(100,Math.round((live/Math.max(1,rules.length))*100))}%"></i></span><span class="domain-chevron">${open?'−':'+'}</span></button>${open?`<div class="ent-domain-body">${children(s.id).map(k=>renderSubsection(k.id)).join('')}${directRules(s.id).filter(matchesRule).map(renderRuleRow).join('')}</div>`:''}</section>`;}
function renderConnection(compact=false){const real=state.session?.mode==='WINDOWS',i=state.inventory;if(i)return `<div class="conn ${compact?'compact':''} ok"><span class="conn-orb"></span><div><small>${tr('connected')}</small><strong>${esc(i.domain)}</strong><span>${esc(i.domainController)} · ${esc(i.executionUser)}</span></div>${compact?'':`<div class="conn-actions"><button data-discover>${tr('refresh')}</button><button data-disconnect>${tr('logout')}</button></div>`}</div>`;if(!real)return `<div class="conn ${compact?'compact':''} warn"><span class="conn-orb"></span><div><small>${tr('setup')}</small><strong>Local-only setup</strong><span>Configure domain and writable DC before enabling writes.</span></div>${compact?'':`<button data-settings>${tr('settings')}</button>`}</div>`;return `<form id="gpo-login" class="conn login ${compact?'compact':''}"><span class="conn-orb"></span><div><small>${tr('connect')}</small><strong>Windows / Active Directory</strong><span>Credentials remain in short-lived server memory only.</span></div>${compact?'':`<div class="login-fields"><input name="userName" placeholder="DOMAIN\\Administrator" autocomplete="off"><input name="password" type="password" placeholder="Password" autocomplete="off"><button class="primary">Connect</button></div>`}</form>`;}
function environmentHealth(){const connected=!!state.inventory,windows=state.session?.mode==='WINDOWS';const live=state.readiness?.checks||[];const base=[['Local agent','PASS','Listening on 127.0.0.1'],['Windows engine',windows?'PASS':'FAIL',windows?'Windows/AD mode active':'Setup mode'],['AD session',connected?'PASS':'FAIL',connected?state.inventory.domain:'Not connected'],['Writable DC',connected?'PASS':'FAIL',connected?state.inventory.domainController:'Not selected']];const checks=[...base,...live.map(x=>[x.label,x.state,x.message])];return `<section class="health-panel panel"><div class="panel-head"><div><span class="panel-kicker">ENVIRONMENT HEALTH</span><h2>Pre-flight readiness</h2></div><span class="probe-badge">${state.readiness?.ready?'READY':'LIVE PROBES'}</span></div><div class="health-grid">${checks.map(c=>{const st=String(c[1]).toUpperCase(),cls=st==='PASS'?'ok':st==='FAIL'?'bad':'pending';return `<div class="health-item ${cls}"><span>${st==='PASS'?'✓':st==='FAIL'?'!':'·'}</span><div><strong>${esc(c[0])}</strong><small>${esc(c[2])}</small></div></div>`}).join('')}</div></section>`;}
function dashboardView(){const m=state.catalog.meta;const ready=state.catalog.rules.filter(r=>r.implementation==='live').length,manual=state.catalog.rules.filter(r=>r.automation==='Manual').length;const failed=state.history.filter(h=>!['SUCCESS','APPLIED','VERIFIED','ROLLED_BACK'].includes(String(h.result?.state||'').toUpperCase())).length;const rollback=state.history.filter(h=>h.result?.state!=='ROLLED_BACK').length;const recent=state.history.slice(0,5);return `<div class="hero"><div><span class="eyebrow">GPO REMEDIATION CONTROL PLANE</span><h1>${tr('dashboard')}</h1><p>CIS controls, Active Directory policy changes, verification and recovery in one controlled workspace.</p></div><div class="hero-badge"><span>LOCAL AGENT</span><strong>${state.session?.mode==='WINDOWS'?'REAL AD':'SETUP'}</strong></div></div>${renderConnection()}<div class="dash-grid"><div class="kpi primary"><span>Benchmark coverage</span><strong>${m.reportedRecipeCount}</strong><small>CIS v4.0.0 controls</small></div><div class="kpi"><span>${tr('ready')}</span><strong>${ready}</strong><small>backend mappings</small></div><div class="kpi"><span>Mapping backlog</span><strong>${m.reportedRecipeCount-ready}</strong><small>UI catalogued</small></div><div class="kpi"><span>Manual controls</span><strong>${manual}</strong><small>review required</small></div><div class="kpi ${failed?'danger':''}"><span>Review required</span><strong>${failed}</strong><small>operations</small></div><div class="kpi"><span>Rollback available</span><strong>${rollback}</strong><small>captured operations</small></div></div>${environmentHealth()}<div class="dash-panels"><section class="panel"><div class="panel-head"><div><span class="panel-kicker">BENCHMARK</span><h2>Control coverage</h2></div><a href="#/benchmark">Open catalog →</a></div><div class="coverage-bars">${topSections().slice(0,8).map(s=>{const rr=descendants(s.id),lv=rr.filter(r=>r.implementation==='live').length;return `<div class="coverage-row"><span class="coverage-domain"><b>${esc(s.id)}</b>${esc(s.title)}</span><span class="coverage-track"><i style="width:${Math.max(2,(lv/Math.max(1,rr.length))*100)}%"></i></span><strong>${lv}/${rr.length}</strong></div>`}).join('')}</div></section><section class="panel"><div class="panel-head"><div><span class="panel-kicker">ACTIVITY</span><h2>${tr('history')}</h2></div><a href="#/operations">View all →</a></div>${recent.length?`<div class="activity-list">${recent.map(h=>`<button data-op="${esc(h.id)}"><span class="activity-state ${String(h.result?.state||'').toLowerCase()}"></span><span><strong>${esc(h.plan?.preview?.gpo?.name||'GPO operation')}</strong><small>${esc(h.result?.state||'UNKNOWN')} · ${esc(h.plan?.selection?.setting||'policy change')}</small></span><b>›</b></button>`).join('')}</div>`:`<div class="panel-empty">${tr('noHistory')}</div>`}</section></div>`;}
function benchmarkView(){const m=state.catalog.meta;return `<div class="hero compact"><div><span class="eyebrow">CIS BENCHMARK LIBRARY</span><h1>${tr('domains')}</h1><p>Navigate by domain, use saved views, and favorite recurring controls without flattening the benchmark hierarchy.</p></div><div class="hero-actions"><div class="hero-badge"><span>CIS</span><strong>v4.0.0</strong></div></div></div><div class="catalog-summary"><span><b>${topSections().length}</b> domains</span><span><b>${m.reportedRecipeCount}</b> controls</span><span><b>${m.levels.L1}</b> L1</span><span><b>${m.levels.L2}</b> L2</span><span><b>${m.liveMappings}</b> ready</span><span><b>${state.favorites.size}</b> favorites</span></div><div class="saved-views"><button data-view="ALL" class="${state.savedView==='ALL'?'active':''}">All controls</button><button data-view="FAVORITES" class="${state.savedView==='FAVORITES'?'active':''}">★ Favorites</button><button data-view="READY" class="${state.savedView==='READY'?'active':''}">Remediation ready</button><button data-view="HIGH" class="${state.savedView==='HIGH'?'active':''}">High impact</button></div><section class="catalog-shell"><div class="catalog-toolbar"><div class="searchbox"><span>⌕</span><input id="catalog-search" value="${esc(state.query)}" placeholder="${tr('search')}"></div><select id="catalog-level"><option value="ALL">${tr('allLevels')}</option><option value="L1" ${state.level==='L1'?'selected':''}>L1</option><option value="L2" ${state.level==='L2'?'selected':''}>L2</option><option value="NG" ${state.level==='NG'?'selected':''}>NG</option></select><select id="catalog-automation"><option value="ALL">${tr('allTypes')}</option><option value="Automated" ${state.automation==='Automated'?'selected':''}>Automated</option><option value="Manual" ${state.automation==='Manual'?'selected':''}>Manual</option></select></div><div class="domain-stack">${topSections().map(renderDomain).join('')}</div></section>`;}
function ensureSelection(){const r=state.selectedRule;if(!r)return;state.selection.setting=r.backendSetting||'';const st=state.settings.find(x=>x.id===r.backendSetting);if(st){if(st.allowValueOverride&&st.suggested!=null)state.selection.value=st.suggested;if(st.requiresInput&&state.selection.customValue==null)state.selection.customValue=st.inputDefault||'';state.selection.accountScope=st.domainPolicySensitive?'Domain':'LocalComputers';}if(state.inventory){if(!state.inventory.gpos.some(g=>g.id===state.selection.gpoId&&g.selectable))state.selection.gpoId='';const scopes=st?.domainPolicySensitive?state.inventory.scopes.filter(x=>x.kind==='Domain'):state.inventory.scopes;if(!scopes.some(x=>x.dn===state.selection.scopeDn))state.selection.scopeDn=scopes[0]?.dn||'';}}
function gpoPicker(){const i=state.inventory;if(!i)return'';const selected=selectedGpo();const q=state.gpoSearch.trim().toLowerCase();const items=i.gpos.filter(g=>!q||g.name.toLowerCase().includes(q)).slice(0,40);return `<div class="gpo-picker"><button type="button" class="gpo-picker-trigger" data-gpo-toggle><span><small>Selected GPO</small><strong>${selected?esc(selected.name):'Choose a Group Policy Object'}</strong></span><b>⌄</b></button>${state.gpoPickerOpen?`<div class="gpo-popover"><div class="gpo-search"><span>⌕</span><input id="gpo-search" value="${esc(state.gpoSearch)}" placeholder="Search GPO by name…" autofocus></div><div class="gpo-results">${items.map(g=>`<button type="button" data-gpo="${esc(g.id)}" ${g.selectable?'':'disabled'}><span><strong>${esc(g.name)}</strong><small>${g.protected?'Protected · ':''}${g.selectable?'Selectable':'Unavailable for this workflow'}</small></span><b>${g.id===state.selection.gpoId?'✓':'›'}</b></button>`).join('')||'<div class="no-results">No matching GPO</div>'}</div></div>`:''}</div>`;}
function stepper(active){const steps=['Control','Target','Preview','Approval','Apply','Verify'];return `<div class="stepper">${steps.map((s,idx)=>`<div class="step ${idx+1<active?'done':idx+1===active?'active':''}"><b>${idx+1<active?'✓':idx+1}</b><span>${s}</span></div>`).join('')}</div>`;}
function currentStep(){if(state.history[0]?.plan?.selection?.setting===state.selectedRule?.backendSetting&&location.hash==='#/control')return 6;if(state.plan&&state.approval.reviewed)return 4;if(state.plan)return 3;if(state.selection.gpoId)return 2;return 1;}
function controlHeader(r){const d=topDomainForRule(r),risk=riskFor(r);return `<div class="control-header"><button class="back-link" data-back>← ${tr('back')}</button><div class="control-title-row"><div class="control-id-block"><span>${esc(r.id)}</span><small>${esc(d?.title||'CIS Control')}</small></div><div class="control-title"><div class="control-badges">${badges(r)}<span class="risk-pill ${risk.cls}">${risk.name} ${tr('risk')}</span></div><h1>${esc(r.title)}</h1></div><button class="favorite-action ${state.favorites.has(r.id)?'active':''}" data-favorite="${esc(r.id)}">${state.favorites.has(r.id)?'★ Saved':'☆ Save'}</button></div>${stepper(currentStep())}<div class="control-tabs">${[['overview',tr('overview')],['remediation',tr('remediation')],['impact',tr('impact')],['verification',tr('verification')],['audit',tr('audit')]].map(([k,l])=>`<button data-tab="${k}" class="${state.tab===k?'active':''}">${l}</button>`).join('')}</div></div>`;}
function overviewTab(r){const risk=riskFor(r);return `<div class="tab-grid"><section class="content-card span2"><span class="card-kicker">CONTROL INTENT</span><h2>What this control changes</h2><p class="long-copy">${esc(r.description||'No description was included in the imported benchmark text.')}</p></section><section class="content-card"><span class="card-kicker">RECOMMENDED STATE</span><h2>${esc(r.recommended||'See benchmark text')}</h2><p>This value comes from the imported CIS Benchmark v4.0.0 recipe.</p></section><section class="content-card risk-card ${risk.cls}"><span class="card-kicker">OPERATIONAL RISK</span><h2>${risk.name}</h2><p>${esc(risk.copy)}</p></section><section class="content-card"><span class="card-kicker">IMPLEMENTATION</span><h2>${r.implementation==='live'?'Automated remediation ready':r.implementation==='manual'?'Manual / read-only control':'Mapping unavailable'}</h2><p>${r.implementation==='live'?'This control has a server-authoritative production mapping and can generate a real GPO preview.':r.implementation==='manual'?'The imported CIS catalog does not classify this control as safely automated. The product keeps it visible but blocks automatic writes.':'No server-authoritative mapping is available for this control.'}</p></section><section class="content-card"><span class="card-kicker">CLASSIFICATION</span><div class="fact-list"><span><b>Level</b>${esc(r.level)}</span><span><b>Type</b>${esc(r.automation)}</span><span><b>Section</b>${esc(sectionTitle(r.sectionId))}</span><span><b>Benchmark</b>CIS v4.0.0</span></div></section><section class="content-card span2 help-card"><span class="card-kicker">CONTEXTUAL GUIDANCE</span><div class="guidance-grid"><div><b>When to use</b><p>Apply when this control belongs to the intended server/workstation baseline and the selected GPO scope is correct.</p></div><div><b>Before change</b><p>Review application dependencies, policy precedence and affected objects. Generate a read-only plan first.</p></div><div><b>After change</b><p>Verify GPO publication, link state, gpupdate and effective policy. Pending probes must remain pending.</p></div></div></section></div>`;}
function targetForm(r){const i=state.inventory,s=state.selection,st=state.settings.find(x=>x.id===r.backendSetting);if(!i)return `<div class="locked-state">${renderConnection()}<h3>Connect to Active Directory to select a real GPO and target scope.</h3></div>`;const scopes=st?.domainPolicySensitive?i.scopes.filter(x=>x.kind==='Domain'):i.scopes;const desired=st?.requiresInput?`<label>${esc(st.inputLabel||'Required value')}<input name="customValue" value="${esc(s.customValue||st.inputDefault||'')}" maxlength="4096" required></label>`:st?.allowValueOverride?`<label>Desired value <span class="unit">${esc(st.unit||'value')}</span><input type="number" name="value" min="${st.minimum??0}" max="${st.maximum??99999}" value="${s.value}"></label>`:`<label>Desired benchmark state<input disabled value="${esc(st?.recommended||'Fixed production mapping')}"></label>`;return `<form id="gpo-selection" class="target-form"><div class="form-section-title"><span>01</span><div><small>TARGET</small><h2>${tr('target')}</h2></div></div>${gpoPicker()}<div class="form-grid"><label>Policy target<input disabled value="${esc(st?.scope||'Computer')} policy"></label><label>Link target<select name="scopeDn" required>${scopes.map(x=>`<option value="${esc(x.dn)}" ${s.scopeDn===x.dn?'selected':''}>${esc(x.name)} · ${esc(x.kind)} · ${esc(x.dn)}</option>`).join('')}</select></label>${r.implementation==='live'?desired:`<label>Desired value<input disabled value="Manual/review-only control"></label>`}<label>Policy refresh<select name="refresh"><option value="None" ${s.refresh==='None'?'selected':''}>Do not force update</option><option value="Pdc" ${s.refresh==='Pdc'?'selected':''}>PDC emulator only</option><option value="Scope" ${s.refresh==='Scope'?'selected':''}>Selected scope computers</option></select></label></div><label class="switch-row"><input type="checkbox" name="firstLink" ${s.firstLink?'checked':''}><span><b>Highest link priority</b><small>Move the selected link to first position. Existing Enforced and filtering settings are not changed.</small></span></label><button class="primary-action" ${r.implementation==='live'&&s.gpoId?'':'disabled'}>${tr('preview')} <span>→</span></button></form>`;}
function impactTab(r){const risk=riskFor(r),g=selectedGpo(),scope=state.inventory?.scopes.find(x=>x.dn===state.selection.scopeDn),live=state.plan?.preview?.impact,conflicts=live?.conflicts||[],ao=live?.affectedObjects;const graphNodes=[['Domain root',state.inventory?.domain||'Not connected'],['Selected GPO',g?.name||'Not selected'],['Target scope',scope?.name||'Not selected'],['Effective policy',state.plan?'Verification after Apply':'Preview required']];return `<div class="impact-layout"><section class="impact-hero ${risk.cls}"><span>IMPACT ANALYSIS</span><h2>${risk.name} operational impact</h2><p>${esc(risk.copy)}</p></section><div class="impact-grid"><section class="content-card"><span class="card-kicker">SELECTED GPO</span><h2>${g?esc(g.name):'Not selected'}</h2><div class="fact-list"><span><b>Protected</b>${g?.protected?'Yes':'No'}</span><span><b>Selectable</b>${g?.selectable?'Yes':'No'}</span></div></section><section class="content-card"><span class="card-kicker">TARGET SCOPE</span><h2>${scope?esc(scope.name):'Not selected'}</h2><p>${scope?esc(scope.dn):'Choose a domain/OU target in Remediation.'}</p></section><section class="content-card span2 conflict-card"><div class="card-title-row"><div><span class="card-kicker">POLICY CONFLICT GRAPH</span><h2>Inheritance & precedence path</h2></div><span class="probe-badge">${live?'LIVE ANALYSIS':'PREVIEW REQUIRED'}</span></div><div class="policy-graph">${graphNodes.map((n,i)=>`<div class="graph-node ${i===1?'focus':''}"><span>${i+1}</span><div><small>${esc(n[0])}</small><strong>${esc(n[1])}</strong></div></div>${i<graphNodes.length-1?'<i>↓</i>':''}`).join('')}</div>${live?`<div class="warning-list">${conflicts.length?conflicts.map((c,i)=>`<div><b>${esc(c.severity||'!')}</b><span>${esc(c.message)}</span></div>`).join(''):'<div><b>✓</b><span>No conflicting definition was detected in the analyzed inheritance path.</span></div>'}</div><p class="engine-note">Inheritance: ${esc(live.inheritance)} · WMI filter: ${esc(live.wmiFilter||'none')} · Security filtering: ${esc((live.securityFiltering||[]).join(', ')||'none detected')}</p>`:'<p class="engine-note">Generate a read-only plan to run live inheritance, precedence, security filtering and WMI analysis.</p>'}</section><section class="content-card span2 affected-card"><div class="card-title-row"><div><span class="card-kicker">AFFECTED OBJECTS EXPLORER</span><h2>Scope inventory</h2></div><span class="probe-badge">${ao?'LIVE INVENTORY':'PREVIEW REQUIRED'}</span></div><div class="object-stats"><div><strong>${ao?.computers??'—'}</strong><span>Computers</span></div><div><strong>${ao?.servers??'—'}</strong><span>Servers</span></div><div><strong>${ao?.workstations??'—'}</strong><span>Workstations</span></div><div><strong>${ao?.disabled??'—'}</strong><span>Disabled</span></div></div>${ao?`<div class="object-placeholder"><span>⌁</span><p>${ao.truncated?'Inventory capped at 5,000 objects. ':''}${ao.users?`${ao.users} enabled users in scope. `:''}Sample: ${esc((ao.sampleHosts||[]).slice(0,8).join(', ')||'No DNS hostnames returned.')}</p></div>`:'<div class="object-placeholder"><span>⌁</span><p>Generate a plan to load the directory scope inventory.</p></div>'}</section></div></div>`;}
function planBlock(r){const p=state.plan;if(!p)return `<div class="preview-empty dryrun-empty"><span>DRY RUN / WHAT-IF</span><h3>No read-only plan generated yet.</h3><p>Select a GPO and target, then generate a plan. The preview performs no domain write.</p><div class="dryrun-features"><span>Before/after diff</span><span>Link intent</span><span>Warning aggregation</span><span>Rollback context</span></div></div>`;const before=p.preview.previousValue??'Not configured',after=p.preview.desiredValue??p.selection.customValue??p.selection.value;return `<section class="plan-card"><div class="plan-head"><div><span>DRY RUN · READ-ONLY PREVIEW</span><h2>Change plan ready</h2></div><span class="safe-badge">NO WRITE YET</span></div><div class="diff-card"><div class="diff-head"><span>BEFORE / AFTER DIFF</span><strong>${esc(r.id)}</strong></div><div class="diff-row"><div class="diff-before"><small>CURRENT</small><strong>${esc(before)}</strong></div><span class="diff-arrow">→</span><div class="diff-after"><small>DESIRED</small><strong>${esc(after)}</strong></div></div></div><div class="plan-facts"><div><span>GPO</span><strong>${esc(p.preview.gpo.name)}</strong></div><div><span>Target</span><strong>${esc(p.preview.scope.dn)}</strong></div><div><span>Link</span><strong>${p.preview.existingLink?'Existing link':'New link'}${p.selection.firstLink?' · priority 1':''}</strong></div><div><span>Execution</span><strong>${esc(p.executionUser)}</strong></div><div><span>gpupdate</span><strong>${p.preview.refreshComputers?.length?`${p.preview.refreshComputers.length} target(s)`:'Not requested'}</strong></div><div><span>Rollback</span><strong>Backup before write</strong></div></div>${p.preview.warnings?.length?`<div class="warning-list">${p.preview.warnings.map((w,i)=>`<div><b>!</b><span>${esc(w)}</span></div>`).join('')}</div>`:''}<div class="approval-box"><div class="form-section-title"><span>04</span><div><small>GOVERNANCE</small><h2>${tr('approval')}</h2></div></div><div class="form-grid"><label>Change / Ticket ID<input id="approval-ref" value="${esc(state.approval.reference)}" placeholder="CHG-2026-001"></label><label>Reviewed / Approved by<input id="approval-by" value="${esc(state.approval.approver)}" placeholder="Name or operator"></label></div><label class="switch-row"><input id="approval-ok" type="checkbox" ${state.approval.reviewed?'checked':''}><span><b>Impact reviewed and approved</b><small>I reviewed the target, GPO, scope and potential precedence impact.</small></span></label>${state.approval.reviewed?`<form id="gpo-apply" class="apply-box"><label class="switch-row"><input name="impact" type="checkbox" required><span><b>Confirm production impact</b><small>Backup will be created before the GPO write.</small></span></label>${p.preview.gpo.protected?`<label class="switch-row danger"><input name="protected" type="checkbox" required><span><b>Protected GPO confirmation</b><small>I explicitly approve changing this protected/default policy.</small></span></label>`:''}<label>Type APPLY to continue<input name="confirmation" required autocomplete="off" placeholder="APPLY"></label><button class="danger-action">Backup → Apply → Link → Verify</button></form>`:''}</div></section>`;}
function remediationTab(r){return `<div class="remediation-layout"><section class="content-card target-card">${targetForm(r)}</section><section>${planBlock(r)}</section></div>`;}
function verificationTimeline(h){if(!h)return `<div class="verification-empty"><div class="radar"></div><h2>No verification run for this control yet</h2><p>After Apply, this workspace will show GPO write, link, gpupdate, replication and effective-policy status.</p></div>`;const rr=h.result.refreshResults||[],v=h.result.verification,ec=h.result.endpointChecks||[];const refreshOk=rr.length&&rr.every(x=>['OK','SUCCESS','SCHEDULED'].includes(String(x.state).toUpperCase()));const effective=String(h.result.effectiveStatus||'ENDPOINT_VERIFICATION_PENDING');const effBad=/MISMATCH|FAILED/.test(effective),effOk=/VERIFIED|MATCHES/.test(effective)&&!/PENDING/.test(effective);const stages=[['GPO write',h.result.gpoPublished?'Verified':'Not confirmed',h.result.gpoPublished?'ok':'bad'],['Link verification',h.result.linkVerified?'Verified':'Not confirmed',h.result.linkVerified?'ok':'bad'],['gpupdate',rr.length?rr.map(x=>`${x.computer}: ${x.state}`).join(' · '):'Not requested',rr.length?(refreshOk?'ok':'bad'):'pending'],['AD / SYSVOL replication',v?(v.replicationConverged?'Converged across checked DCs':(v.replicationWarnings||[]).join(' · ')||'Pending'):'Not checked',v?(v.replicationConverged?'ok':'pending'):'pending'],['Effective policy',effective+(ec.length?` · ${ec.map(x=>`${x.hostname}: ${x.state}`).join(' · ')}`:''),effBad?'bad':effOk?'ok':'pending']];return `<div class="verify-timeline">${stages.map((st,i)=>`<div class="verify-node ${st[2]}"><span>${st[2]==='ok'?'✓':st[2]==='bad'?'!':i+1}</span><div><small>STAGE ${i+1}</small><h3>${st[0]}</h3><p>${esc(st[1])}</p></div></div>`).join('')}</div>`;}
function verificationTab(r){const h=relevantHistory(r)[0];return `<div class="verify-page"><div class="section-intro"><span>POST-CHANGE ASSURANCE</span><h2>Verification pipeline</h2><p>Each stage must be independently confirmed. Pending probes are never displayed as passed.</p></div>${verificationTimeline(h)}<section class="content-card evidence-card"><div class="card-title-row"><div><span class="card-kicker">EVIDENCE PACK</span><h2>Change evidence & audit bundle</h2></div><button data-evidence ${h?'':'disabled'}>Prepare JSON evidence</button></div><div class="evidence-grid"><span>Before value</span><span>After value</span><span>GPO & target</span><span>Operator</span><span>Backup ID</span><span>Verification</span></div><p>${h?'Evidence can be generated from the recorded operation currently loaded in the browser.':'Apply and record an operation before generating evidence.'}</p></section></div>`;}
function auditTab(r){const hs=relevantHistory(r);return `<div class="audit-page"><div class="section-intro"><span>CONTROL AUDIT TRAIL</span><h2>${esc(r.id)} operation history</h2><p>Operator, target, backup and recovery context for this control.</p></div>${hs.length?`<div class="audit-table"><div class="audit-head"><span>Operation</span><span>GPO</span><span>State</span><span>Backup</span><span>Action</span></div>${hs.map(h=>`<div class="audit-row"><span><b>${esc(h.id)}</b><small>${esc(h.plan?.executionUser||'—')}</small></span><span>${esc(h.plan?.preview?.gpo?.name||'—')}</span><span><i class="state-dot ${String(h.result?.state||'').toLowerCase()}"></i>${esc(h.result?.state||'UNKNOWN')}</span><span>${esc(h.result?.backupId||'—')}</span><span><button data-verify="${esc(h.id)}">Re-verify</button></span></div>`).join('')}</div>`:`<div class="panel-empty">No operation has been recorded for this control.</div>`}</div>`;}
function controlView(){const r=state.selectedRule;if(!r)return `<div class="missing-control"><h1>${tr('noSelection')}</h1><a href="#/benchmark">${tr('back')}</a></div>`;ensureSelection();let body=state.tab==='overview'?overviewTab(r):state.tab==='remediation'?remediationTab(r):state.tab==='impact'?impactTab(r):state.tab==='verification'?verificationTab(r):auditTab(r);return `${controlHeader(r)}<div class="control-body">${body}</div>`;}
function operationsView(){const all=state.history,filtered=state.opsFilter==='ALL'?all:all.filter(h=>String(h.result?.state||'').toUpperCase()===state.opsFilter);const counts={SUCCESS:all.filter(h=>['SUCCESS','APPLIED','VERIFIED'].includes(String(h.result?.state||'').toUpperCase())).length,FAILED:all.filter(h=>['FAILED','REVIEW_REQUIRED','PARTIAL'].includes(String(h.result?.state||'').toUpperCase())).length,ROLLED_BACK:all.filter(h=>String(h.result?.state||'').toUpperCase()==='ROLLED_BACK').length};return `<div class="hero compact"><div><span class="eyebrow">CHANGE & RECOVERY CENTER</span><h1>${tr('operations')}</h1><p>Review completed changes, verification state, backups and rollback availability.</p></div></div><div class="ops-metrics"><button data-ops-filter="ALL" class="${state.opsFilter==='ALL'?'active':''}"><span>All</span><strong>${all.length}</strong></button><button data-ops-filter="SUCCESS" class="${state.opsFilter==='SUCCESS'?'active':''}"><span>Successful</span><strong>${counts.SUCCESS}</strong></button><button data-ops-filter="FAILED" class="${state.opsFilter==='FAILED'?'active':''}"><span>Review</span><strong>${counts.FAILED}</strong></button><button data-ops-filter="ROLLED_BACK" class="${state.opsFilter==='ROLLED_BACK'?'active':''}"><span>Rolled back</span><strong>${counts.ROLLED_BACK}</strong></button></div>${filtered.length?`<div class="ops-list">${filtered.map(h=>operationCard(h)).join('')}</div>`:`<div class="panel-empty">${tr('noHistory')}</div>`}`;}
function operationCard(h){const rr=h.result?.refreshResults||[];return `<article class="op-card"><div class="op-main"><span class="op-state ${String(h.result?.state||'').toLowerCase()}">${esc(h.result?.state||'UNKNOWN')}</span><div><h2>${esc(h.plan?.preview?.gpo?.name||'GPO operation')}</h2><p>${esc(h.result?.message||'')}</p><div class="op-meta"><span>${esc(h.plan?.preview?.scope?.dn||'—')}</span><span>${esc(h.plan?.executionUser||'—')}</span><span>Backup ${esc(h.result?.backupId||'—')}</span></div></div></div><div class="op-verify"><span class="${h.result?.gpoPublished?'ok':'bad'}">${h.result?.gpoPublished?'✓':'!'} GPO</span><span class="${h.result?.linkVerified?'ok':'bad'}">${h.result?.linkVerified?'✓':'!'} Link</span><span class="${rr.length?'ok':'pending'}">${rr.length?'✓':'·'} gpupdate</span><span class="${h.result?.verification?.replicationConverged?'ok':'pending'}">${h.result?.verification?.replicationConverged?'✓':'·'} Replication</span><span class="${/VERIFIED|MATCHES/.test(String(h.result?.effectiveStatus||''))&&!/PENDING/.test(String(h.result?.effectiveStatus||''))?'ok':/MISMATCH|FAILED/.test(String(h.result?.effectiveStatus||''))?'bad':'pending'}">${/VERIFIED|MATCHES/.test(String(h.result?.effectiveStatus||''))&&!/PENDING/.test(String(h.result?.effectiveStatus||''))?'✓':'·'} Effective</span></div><div class="op-actions"><button data-verify="${esc(h.id)}">Re-verify</button>${h.result?.state==='ROLLED_BACK'?'':`<form data-rollback="${esc(h.id)}"><input name="confirmation" placeholder="ROLLBACK" required><button>Rollback</button></form>`}</div></article>`;}
function saveFavorites(){localStorage.setItem('gr-favorites',JSON.stringify([...state.favorites]));}
function toggleFavorite(id){state.favorites.has(id)?state.favorites.delete(id):state.favorites.add(id);saveFavorites();render();}
function notifications(){const items=[];if(state.session?.mode!=='WINDOWS')items.push(['Setup required','Windows / AD engine is not active yet.']);if(!state.inventory)items.push(['AD not connected','Connect before generating a real remediation plan.']);const review=state.history.filter(h=>['FAILED','REVIEW_REQUIRED','PARTIAL'].includes(String(h.result?.state||'').toUpperCase())).length;if(review)items.push(['Operations need review',`${review} operation(s) require attention.`]);if(state.readiness&&!state.readiness.ready)items.push(['Environment needs attention','One or more required backend readiness checks did not pass.']);return items;}
function overlays(){const notes=notifications();return `${state.notificationOpen?`<div class="overlay-backdrop" data-close-overlay></div><aside class="notification-panel"><div class="overlay-head"><div><span>NOTIFICATION CENTER</span><h2>Attention & status</h2></div><button data-close-overlay>×</button></div><div class="notification-list">${notes.map((n,i)=>`<div><b>${i+1}</b><span><strong>${esc(n[0])}</strong><small>${esc(n[1])}</small></span></div>`).join('')}</div></aside>`:''}${state.commandOpen?`<div class="command-overlay"><div class="command-palette"><div class="command-search"><span>⌘</span><input id="command-input" placeholder="Search controls or actions…" autofocus></div><div class="command-groups"><small>NAVIGATION</small><button data-command="dashboard"><span>⌂</span><b>Open Dashboard</b><kbd>G D</kbd></button><button data-command="benchmark"><span>▦</span><b>Open Benchmark</b><kbd>G B</kbd></button><button data-command="operations"><span>≋</span><b>Open Operations</b><kbd>G O</kbd></button><small>ACTIONS</small><button data-command="favorites"><span>★</span><b>Show Favorites</b><kbd>F</kbd></button><button data-command="refresh"><span>↻</span><b>Refresh environment</b><kbd>R</kbd></button></div></div></div>`:''}`;}
function downloadEvidence(){const r=state.selectedRule,h=relevantHistory(r||{})[0];if(!r||!h)return;const payload={product:'GPO Remediator',benchmark:'CIS v4.0.0',control:{id:r.id,title:r.title,recommended:r.recommended},operation:h,generatedAt:new Date().toISOString()};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`gpo-evidence-${r.id.replaceAll('.','-')}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function applyTheme(){document.documentElement.dataset.grTheme=state.theme;localStorage.setItem('gr-theme',state.theme);}
function noticeTone(message){const m=String(message||'').toLowerCase();if(/fail|error|unable|blocked|invalid/.test(m))return'error';if(/warning|review|required|pending/.test(m))return'warning';if(/success|connected|generated|completed|verified|loaded/.test(m))return'success';return'info';}
function productFooter(){const mode=state.session?.mode==='WINDOWS'?'REAL AD':'LOCAL';return `<footer class="product-footer" aria-label="Product information"><span><b>GPO Remediator</b> · CIS v4.0.0</span><span>Build ${esc(state.buildLabel)} · ${mode} MODE · 127.0.0.1</span></footer>`;}
function busyLayer(){return state.busy?`<div class="busy-layer" role="status" aria-live="polite"><div class="busy-card"><span class="busy-spinner"></span><div><strong>Processing request</strong><small>Please keep this window open.</small></div></div></div>`:'';}
function render(){if(!page||!state.catalog)return;applyTheme();const real=state.session?.mode==='WINDOWS';bar.innerHTML=`<div class="service-left"><span class="agent-mark"></span><div><strong>GPO Remediator</strong><small>${real?'REAL AD ENGINE':'LOCAL SETUP'} · ${state.service?.writesEnabled?'writes enabled':'writes disabled'}</small></div></div><div class="service-right"><button data-command-open title="Command palette" aria-label="Open command palette">⌘K <span>Command</span></button><button data-notifications title="Notifications" aria-label="Open notifications">◇ <span>${notifications().length}</span></button><button data-refresh title="${tr('refresh')}" aria-label="${tr('refresh')}">↻ <span>${tr('refresh')}</span></button><button data-theme title="${tr('theme')}" aria-label="Toggle theme">${state.theme==='dark'?'☀':'◐'} <span>${state.theme==='dark'?'Light':'Dark'}</span></button><button data-lang aria-label="Switch language">${state.lang.toUpperCase()}</button><button data-settings aria-label="${tr('settings')}">⚙ <span>${tr('settings')}</span></button></div>`;const route=location.hash||'#/dashboard';const main=(route==='#/dashboard'?dashboardView():route==='#/benchmark'?benchmarkView():route==='#/control'?controlView():operationsView());const toast=state.notice?`<div class="toast ${noticeTone(state.notice)}" role="status" aria-live="polite"><span class="toast-mark"></span><span>${esc(state.notice)}</span></div>`:'';page.innerHTML=`<main class="product-main" aria-busy="${state.busy?'true':'false'}">${main}</main>${productFooter()}${toast}${overlays()}${busyLayer()}`;if(state.busy)page.querySelectorAll('button,input,select,textarea').forEach(x=>x.disabled=true);updateNav();}
async function run(fn){if(state.busy)return;state.busy=true;state.notice='';render();try{await fn();}catch(e){state.notice=e.message;}finally{state.busy=false;render();}}
async function refresh(){await loadCatalog();state.session=await api('/session');[state.service,state.settings,state.history]=await Promise.all([api('/service'),api('/gpo/settings'),api('/gpo/history')]);syncBackendMappings();try{state.inventory=await api('/gpo/inventory');state.readiness=await api('/gpo/readiness');}catch{state.inventory=null;state.readiness=null;}render();}
function captureForm(){const f=page.querySelector('#gpo-selection');if(!f)return;const st=state.settings.find(x=>x.id===state.selectedRule?.backendSetting);state.selection.scopeDn=f.elements.scopeDn?.value??state.selection.scopeDn;state.selection.refresh=f.elements.refresh?.value??state.selection.refresh;state.selection.accountScope=st?.domainPolicySensitive?'Domain':'LocalComputers';if(f.elements.value)state.selection.value=Number(f.elements.value.value);if(f.elements.customValue)state.selection.customValue=f.elements.customValue.value;state.selection.firstLink=!!f.elements.firstLink?.checked;state.selection.setting=state.selectedRule?.backendSetting||'';}
function selectRule(id){state.selectedRule=state.catalog.rules.find(r=>r.id===id);state.plan=null;state.tab='overview';state.selection.gpoId='';state.selection.scopeDn='';state.selection.customValue='';state.approval={reference:'',approver:'',reviewed:false};state.gpoSearch='';state.gpoPickerOpen=false;ensureSelection();location.hash='#/control';}
function updateNav(){document.querySelectorAll('[data-gpo-nav]').forEach(a=>a.classList.toggle('selected',a.hash===location.hash||(location.hash==='#/control'&&a.hash==='#/benchmark')));}
function installNav(nav){if(nav.querySelector('[data-gpo-nav]'))return;nav.querySelectorAll('a,button').forEach(a=>a.hidden=true);const items=[['#/dashboard','⌂',tr('dashboard')],['#/benchmark','▦',tr('benchmark')],['#/operations','≋',tr('operations')]];for(const [href,icon,label] of items){const a=document.createElement('a');a.href=href;a.className='nav-link';a.dataset.gpoNav='';a.innerHTML=`<span class="nav-icon">${icon}</span><span>${label}</span>`;nav.append(a);}const set=document.createElement('button');set.className='nav-link';set.dataset.settingsNav='';set.innerHTML=`<span class="nav-icon">⚙</span><span>${tr('settings')}</span>`;set.onclick=()=>window.dispatchEvent(new CustomEvent('gr:open'));nav.append(set);}
function mount(){const workspace=document.querySelector('.workspace'),nav=document.querySelector('.sidebar nav');if(!workspace||!nav)return;document.body.classList.add('operator-custom-page');installNav(nav);if(!document.getElementById('service-bar')){bar=document.createElement('div');bar.id='service-bar';workspace.prepend(bar);page=document.createElement('section');page.id='operator-modules';workspace.insertBefore(page,bar.nextSibling);
page.addEventListener('click',e=>{const dom=e.target.closest('[data-domain]');if(dom){const id=dom.dataset.domain,was=state.expandedTop.has(id);state.expandedTop.clear();if(!was)state.expandedTop.add(id);render();return;}const sub=e.target.closest('[data-subsection]');if(sub){const id=sub.dataset.subsection;state.expandedSub.has(id)?state.expandedSub.delete(id):state.expandedSub.add(id);render();return;}const rule=e.target.closest('[data-rule]');if(rule){selectRule(rule.dataset.rule);return;}const fav=e.target.closest('[data-favorite]');if(fav){e.preventDefault();e.stopPropagation();toggleFavorite(fav.dataset.favorite);return;}const view=e.target.closest('[data-view]');if(view){state.savedView=view.dataset.view;render();return;}if(e.target.closest('[data-bulk-toggle]')){state.bulkMode=!state.bulkMode;if(!state.bulkMode)state.bulkSelection.clear();render();return;}if(e.target.closest('[data-bulk-review]')){state.notice=`${state.bulkSelection.size} controls selected. Bulk execution is UI-only until backend orchestration is implemented.`;render();return;}const tab=e.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;render();return;}if(e.target.closest('[data-back]')){location.hash='#/benchmark';return;}if(e.target.closest('[data-gpo-toggle]')){state.gpoPickerOpen=!state.gpoPickerOpen;render();return;}const gp=e.target.closest('[data-gpo]');if(gp){state.selection.gpoId=gp.dataset.gpo;state.gpoPickerOpen=false;state.gpoSearch='';state.plan=null;render();return;}if(e.target.closest('[data-discover]'))run(async()=>{state.inventory=await api('/gpo/discover',{});state.readiness=await api('/gpo/readiness');});if(e.target.closest('[data-disconnect]'))run(async()=>{await api('/gpo/disconnect',{});state.inventory=null;state.readiness=null;state.plan=null;});if(e.target.closest('[data-settings]'))window.dispatchEvent(new CustomEvent('gr:open'));const of=e.target.closest('[data-ops-filter]');if(of){state.opsFilter=of.dataset.opsFilter;render();return;}const v=e.target.closest('[data-verify]');if(v)run(async()=>{const rr=await api('/gpo/'+v.dataset.verify+'/verify',{});state.history=await api('/gpo/history');state.notice=rr.result.message;});const op=e.target.closest('[data-op]');if(op){location.hash='#/operations';return;}if(e.target.closest('[data-evidence]')){run(async()=>{await downloadEvidence();state.notice='Evidence pack generated from the backend audit record.';});return;}if(e.target.closest('[data-close-overlay]')||e.target.classList.contains('command-overlay')){state.commandOpen=false;state.notificationOpen=false;render();return;}const cmd=e.target.closest('[data-command]');if(cmd){const c=cmd.dataset.command;if(c==='dashboard')location.hash='#/dashboard';if(c==='benchmark')location.hash='#/benchmark';if(c==='operations')location.hash='#/operations';if(c==='favorites'){state.savedView='FAVORITES';location.hash='#/benchmark';}if(c==='refresh')run(refresh);state.commandOpen=false;render();return;}});
page.addEventListener('input',e=>{if(e.target.id==='catalog-search'){state.query=e.target.value;render();return;}if(e.target.id==='gpo-search'){state.gpoSearch=e.target.value;render();return;}if(e.target.id==='approval-ref')state.approval.reference=e.target.value;if(e.target.id==='approval-by')state.approval.approver=e.target.value;if(e.target.id==='approval-ok'){state.approval.reviewed=e.target.checked;render();}if(e.target.id==='exception-enabled'){state.exception.enabled=e.target.checked;render();}if(e.target.id==='exception-reason')state.exception.reason=e.target.value;if(e.target.id==='exception-owner')state.exception.owner=e.target.value;if(e.target.id==='exception-expires')state.exception.expires=e.target.value;if(e.target.matches('[data-bulk-rule]')){e.target.checked?state.bulkSelection.add(e.target.dataset.bulkRule):state.bulkSelection.delete(e.target.dataset.bulkRule);render();}if(e.target.closest('#gpo-selection')){captureForm();state.plan=null;}});
page.addEventListener('change',e=>{if(e.target.id==='catalog-level'){state.level=e.target.value;render();}if(e.target.id==='catalog-automation'){state.automation=e.target.value;render();}if(e.target.closest('#gpo-selection')){captureForm();state.plan=null;render();}});
page.addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(f.id==='gpo-login'){const login={userName:f.elements.userName.value.trim(),password:f.elements.password.value};run(async()=>{try{state.inventory=await api('/gpo/connect',login);state.readiness=await api('/gpo/readiness');state.notice='Connected. Real GPO inventory loaded.';}finally{login.password='';}});}if(f.id==='gpo-selection'){captureForm();if(!state.selectedRule?.backendSetting)return;run(async()=>{state.plan=await api('/gpo/preview',state.selection);state.notice='Read-only plan generated. No domain change has been made.';});}if(f.id==='gpo-apply'&&state.plan){const id=state.plan.id,payload={confirmation:f.elements.confirmation.value,acknowledgeImpact:f.elements.impact.checked,acknowledgeProtected:!!f.elements.protected?.checked,changeReference:state.approval.reference.trim(),approvedBy:state.approval.approver.trim()};run(async()=>{const result=await api('/gpo/'+id+'/apply',payload);state.plan=null;state.history=await api('/gpo/history');state.notice=result.result.state+': '+result.result.message;state.tab='verification';});}if(f.dataset.rollback){const id=f.dataset.rollback;run(async()=>{const result=await api('/gpo/'+id+'/rollback',{confirmation:f.elements.confirmation.value});state.history=await api('/gpo/history');state.notice=result.result.state+': '+result.result.message;});}});
bar.addEventListener('click',e=>{if(e.target.closest('[data-command-open]')){state.commandOpen=true;state.notificationOpen=false;render();return;}if(e.target.closest('[data-notifications]')){state.notificationOpen=true;state.commandOpen=false;render();return;}if(e.target.closest('[data-settings]'))window.dispatchEvent(new CustomEvent('gr:open'));if(e.target.closest('[data-refresh]'))run(refresh);if(e.target.closest('[data-theme]')){state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem('gr-theme',state.theme);render();}if(e.target.closest('[data-lang]')){state.lang=state.lang==='az'?'en':'az';localStorage.setItem('gr-lang',state.lang);nav.querySelectorAll('[data-gpo-nav],[data-settings-nav]').forEach(x=>x.remove());installNav(nav);render();}});}
updateNav();}
async function init(){mount();await refresh();if(!location.hash)location.hash='#/dashboard';window.addEventListener('gr:refresh',()=>run(refresh));window.addEventListener('hashchange',()=>{mount();render();});window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();state.commandOpen=!state.commandOpen;state.notificationOpen=false;render();return;}if(e.key==='Escape'&&(state.commandOpen||state.notificationOpen||state.gpoPickerOpen)){state.commandOpen=false;state.notificationOpen=false;state.gpoPickerOpen=false;render();return;}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){e.preventDefault();location.hash='#/benchmark';setTimeout(()=>document.getElementById('catalog-search')?.focus(),60);}});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
